-- ---------- VERIFICACIÓN (ejecuta estas queries al final) ----------
-- 1. Recuento de filas por tabla (esperado: 14 / 5 / 65 / 125 / 1879 / 2521 / 276)
SELECT 'dim_clientes' t, COUNT(*) n FROM dim_clientes
UNION ALL SELECT 'dim_modelos', COUNT(*) FROM dim_modelos
UNION ALL SELECT 'dim_articulos_inventario', COUNT(*) FROM dim_articulos_inventario
UNION ALL SELECT 'fact_registro_activos', COUNT(*) FROM fact_registro_activos
UNION ALL SELECT 'fact_depreciacion_mensual', COUNT(*) FROM fact_depreciacion_mensual
UNION ALL SELECT 'fact_movimientos_inventario', COUNT(*) FROM fact_movimientos_inventario
UNION ALL SELECT 'fact_conteos_fisicos', COUNT(*) FROM fact_conteos_fisicos;

-- 2. NBV total de la flota (esperado: ~11,1 M€)
SELECT ROUND(SUM(valor_neto_contable)/1e6, 2) AS nbv_millones FROM fact_registro_activos;

-- 3. Integridad: coste - dep_acumulada = NBV en todas las filas (esperado: 0 desviaciones)
SELECT COUNT(*) AS filas_incoherentes
FROM fact_registro_activos
WHERE ABS(coste_adquisicion - dep_acumulada - valor_neto_contable) > 0.01;
